#!/usr/bin/env bash
# Question 1: Worker after a configuration change. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

case "${Q1_FAULT}" in
  kubelet-kubeconfig-server)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q1_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q1_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
  kubelet-client-ca)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q1_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q1_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
  kubelet-config-flag)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q1_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q1_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
  kubelet-kubeconfig-flag)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q1_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q1_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
  kubelet-serving-cert)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q1_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q1_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
  kubelet-max-pods)
    for _ in $(seq 1 60); do
      [[ "$(kubectl get node "${Q1_NODE}" -o jsonpath='{.status.capacity.pods}')" == 2 ]] && break
      sleep 2
    done
    kubectl -n "${Q1_NS}" delete pod -l app=node-agent --field-selector "spec.nodeName=${Q1_NODE}" --wait=false >/dev/null 2>&1 || true
    sleep 15
    ;;
esac
